import stats from "@/lib/build-stats.json";

// What this repository is, measured rather than claimed.
//
// Every number here is generated by scripts/build_stats.py from the
// tracked tree, and CI fails if the committed JSON differs from a fresh
// run. A hand-typed "80,000 lines" is stale the next morning and is
// exactly the sort of assertion the rest of this site exists to argue
// against; a generated one is checkable by cloning the repo and running
// the same script.
//
// The categories are the argument. Markdown is documentation, not code.
// Protobuf is a contract. Generated stubs are neither written nor
// claimed, and are shown precisely so a reader can see they were
// excluded rather than wonder.

type History = {
  commits: number;
  merges: number;
  nonMerge: number;
  byAssistant: number;
  byBot: number;
  byOwner: number;
  days: number;
};

type Category = {
  files: number;
  lines: number;
  languages: { language: string; files: number; lines: number }[];
};

const n = (v: number) => v.toLocaleString("en-US");

const ORDER: { key: keyof typeof stats.lines; label: string; note: string }[] = [
  { key: "code", label: "Code", note: "Written by hand, tests excluded" },
  { key: "tests", label: "Tests", note: "Go, TypeScript and Python" },
  {
    key: "documentation",
    label: "Documentation",
    note: "Specification, decision records, working notes",
  },
  { key: "contract", label: "Contract", note: "Protobuf service definitions" },
  { key: "config", label: "Configuration", note: "YAML and JSON" },
  {
    key: "generated",
    label: "Generated",
    note: "Protobuf stubs and lockfiles, excluded from the figures above",
  },
];

export function BuildStats() {
  const lines = stats.lines as Record<string, Category>;
  const s = stats.structure;
  const h = stats.history as History;
  const code = lines.code?.lines ?? 0;
  const tests = lines.tests?.lines ?? 0;
  const docs = lines.documentation?.lines ?? 0;

  const testRatio = code ? Math.round((tests / code) * 100) : 0;
  const docRatio = code ? Math.round((docs / code) * 100) : 0;

  return (
    <section className="mt-14 border-t border-line pt-10">
      <p className="font-mono text-[11px] tracking-[0.14em] text-accent uppercase">
        the site itself
      </p>
      <h2
        className="font-display mt-3 text-2xl leading-snug text-ink sm:text-3xl"
        style={{ fontVariationSettings: '"opsz" 60, "SOFT" 50' }}
      >
        What this is made of.
      </h2>

      <div className="mt-6 space-y-5 text-base leading-relaxed text-ink-2">
        <p>
          Everything below is counted from the repository at build time,
          not typed in. The script that does it is{" "}
          <code className="bg-paper-2 px-1 py-0.5 font-mono text-[0.9em] text-ink">
            scripts/build_stats.py
          </code>
          , and the build fails if the committed figures differ from a
          fresh count. Clone the repo and run it; you should get these
          numbers.
        </p>
      </div>

      {/* The three that matter, large. Everything else is detail. */}
      <dl className="mt-8 grid gap-px border border-line-strong bg-line-strong sm:grid-cols-3">
        {[
          { label: "lines of code", value: n(code), sub: "tests excluded" },
          {
            label: "lines of tests",
            value: n(tests),
            sub: `${testRatio}% of the code`,
          },
          {
            label: "direct dependencies",
            value: n(s.directDependencies),
            sub: "Go, web and dev combined",
          },
        ].map((m) => (
          <div key={m.label} className="bg-paper-2 px-5 py-6">
            <dd className="font-display text-4xl text-ink tabular-nums">
              {m.value}
            </dd>
            <dt className="mt-2 font-mono text-[11px] tracking-[0.14em] text-ink-3 uppercase">
              {m.label}
            </dt>
            <p className="mt-1 text-sm text-ink-3">{m.sub}</p>
          </div>
        ))}
      </dl>

      <p className="mt-6 text-base leading-relaxed text-ink-2">
        {n(s.directDependencies)} direct dependencies covers a ConnectRPC
        API, vector retrieval, local model inference, PDF generation and
        a timed psychometric instrument. The documentation is{" "}
        <strong className="text-ink">{docRatio}% of the code volume</strong>,
        which is the number least likely to be matched elsewhere and the
        one this site would rather be judged on.
      </p>

      <h3 className="mt-10 font-mono text-[11px] tracking-[0.14em] text-ink-3 uppercase">
        By category
      </h3>
      <table className="mt-4 w-full border-collapse text-sm">
        <thead>
          <tr className="border-b border-line text-left font-mono text-[10px] tracking-[0.14em] text-ink-3 uppercase">
            <th className="py-2 font-normal">Category</th>
            <th className="py-2 text-right font-normal">Files</th>
            <th className="py-2 text-right font-normal">Lines</th>
          </tr>
        </thead>
        <tbody>
          {ORDER.map(({ key, label, note }) => {
            const c = lines[key as string];
            if (!c) return null;
            const excluded = key === "generated";
            return (
              <tr
                key={key as string}
                className={`border-b border-line ${excluded ? "text-ink-3" : "text-ink-2"}`}
              >
                <td className="py-2.5">
                  <span className={excluded ? "" : "text-ink"}>{label}</span>
                  <span className="block text-xs text-ink-3">{note}</span>
                </td>
                <td className="py-2.5 text-right tabular-nums">{n(c.files)}</td>
                <td className="py-2.5 text-right tabular-nums">{n(c.lines)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <h3 className="mt-10 font-mono text-[11px] tracking-[0.14em] text-ink-3 uppercase">
        Languages, code only
      </h3>
      <ul className="mt-4 flex flex-wrap gap-x-6 gap-y-2 text-sm text-ink-2">
        {(lines.code?.languages ?? []).map((l) => (
          <li key={l.language}>
            <span className="text-ink">{l.language}</span>{" "}
            <span className="tabular-nums text-ink-3">{n(l.lines)}</span>
          </li>
        ))}
      </ul>

      {h.commits ? (
        <>
          <h3 className="mt-10 font-mono text-[11px] tracking-[0.14em] text-ink-3 uppercase">
            Who wrote it
          </h3>
          <p className="mt-4 text-base leading-relaxed text-ink-2">
            {n(h.commits)} commits in {h.days} days. That pace is not a
            person typing, and saying so here is better than leaving a
            reader to work it out and wonder what else the page is
            quiet about.
          </p>
          <p className="mt-4 text-base leading-relaxed text-ink-2">
            Of the {n(h.nonMerge)} commits that changed something,{" "}
            <strong className="text-ink">
              {n(h.byAssistant)} were written by an AI assistant
            </strong>{" "}
            working to a specification, {n(h.byOwner)} by Roger directly,
            and {n(h.byBot)} by a dependency bot. He wrote the
            specification, reviewed every change, and merged{" "}
            {n(h.merges)} pull requests. None of that is a claim you have
            to take: clone the repo and run{" "}
            <code className="bg-paper-2 px-1 py-0.5 font-mono text-[0.9em] text-ink">
              git log --no-merges --format=%an | sort | uniq -c
            </code>
            . The <code className="bg-paper-2 px-1 py-0.5 font-mono text-[0.9em] text-ink">--no-merges</code>{" "}
            matters: a merge commit records who pressed the button, so
            without it Roger&rsquo;s {n(h.merges)} merges count as
            authorship and the split looks close to even.
          </p>
          <p className="mt-4 text-base leading-relaxed text-ink-2">
            The skill being demonstrated is not typing speed. It is
            knowing what to specify, what to check, and which failures
            matter: the {n(s.requirements)} tracked requirements, the{" "}
            {n(s.ciChecks)} checks that run on every push, and the
            decision records below are the part a model cannot supply.
          </p>
        </>
      ) : null}

      <h3 className="mt-10 font-mono text-[11px] tracking-[0.14em] text-ink-3 uppercase">
        Decisions, not volume
      </h3>
      <p className="mt-4 text-base leading-relaxed text-ink-2">
        Line counts measure scope. These measure how it is held together.
      </p>
      <dl className="mt-5 grid gap-x-8 gap-y-3 sm:grid-cols-2">
        {[
          [
            `${n(s.requirements)} requirements`,
            `tracked to a state: ${n(s.requirementsShipped)} shipped, ${n(s.requirementsNotBuilt)} not built, and the gap published rather than tidied away`,
          ],
          [
            `${n(s.rpcs)} RPCs across ${n(s.services)} services`,
            "defined in protobuf, with lint, breaking-change checks against main, and a check that regenerating produces no diff",
          ],
          [
            `${n(s.migrations)} migrations`,
            "every one replayed on an empty database on every pull request",
          ],
          [
            `${n(s.goTests)} Go tests, ${n(s.webTests)} web, ${n(s.pythonTests)} Python`,
            "run on every push, alongside the type checks and the build",
          ],
          [
            `${n(s.adrs)} decision records`,
            "short, dated, and kept even when the decision was later reversed",
          ],
          [
            `${n(s.customChecks)} checks written for this repo`,
            "content schema, design tokens, link resolution, no-JavaScript rendering, runtime version drift",
          ],
          [
            `${n(s.runtimeServices)} containers`,
            "Caddy, the web app, the API, a Python sidecar, Postgres with pgvector, object storage, local model inference",
          ],
        ].map(([head, tail]) => (
          <div key={head}>
            <dt className="font-medium text-ink">{head}</dt>
            <dd className="m-0 mt-0.5 text-sm leading-relaxed text-ink-2">
              {tail}
            </dd>
          </div>
        ))}
      </dl>
    </section>
  );
}
